#[test]
fn test_retrieve_envelope_bare_frontmatter_merged() {
    let dir = setup_workspace_with_frontmatter_title();

    write(
        dir.path().join("bare.md"),
        indoc! {"
            title: Bare Title
            status: active
            depends: []

            Body of bare doc.
        "},
    )
    .unwrap();

    let (stdout, stderr, success) = run_iwe(dir.path(), &["-k", "bare", "-d", "0"]);

    assert!(success, "stderr: {}", stderr);

    assert!(stdout.contains("  title: Bare Title"), "title in envelope: {}", stdout);
    assert!(stdout.contains("  status: active"), "status merged: {}", stdout);
    assert!(stdout.contains("Body of bare doc."), "body present: {}", stdout);
    // Front matter lines should not appear in body
    let after_envelope = stdout.split("---\n\n").nth(1).unwrap_or("");
    assert!(!after_envelope.contains("status: active"), "status not in body: {}", after_envelope);
}

#[test]
fn test_retrieve_envelope_reserved_keys_not_overwritten() {
    let dir = setup_workspace_with_frontmatter_title();

    // Frontmatter with a "key" field should not overwrite envelope's key
    write(
        dir.path().join("conflict.md"),
        indoc! {"
            ---
            title: Conflict Test
            key: evil-override
            status: ok
            ---

